public record EnrollmentCheck(int Enrolled, int Seats, bool HasPrerequisite, bool AlreadyEnrolled);

public static class EnrollmentRules
{
    public static string? Problem(EnrollmentCheck c) =>
        c.AlreadyEnrolled ? "Already enrolled"
        : !c.HasPrerequisite ? "Finish the prerequisite first"
        : c.Enrolled >= c.Seats ? "The course is full"
        : null;
}

public class EnrollmentRulesTests
{
    [Fact]
    public void A_student_without_the_prerequisite_is_refused() =>
        Assert.Equal("Finish the prerequisite first",
            EnrollmentRules.Problem(new(Enrolled: 3, Seats: 30, HasPrerequisite: false, AlreadyEnrolled: false)));
}

public class Deadline(TimeProvider clock)
{
    public bool IsLate(DateTimeOffset due) => clock.GetUtcNow() > due;
}

public class DeadlineTests
{
    [Fact]
    public void A_submission_after_the_due_time_is_late()
    {
        var clock = new FakeTimeProvider(new DateTimeOffset(2026, 11, 1, 9, 0, 0, TimeSpan.Zero));
        var deadline = new Deadline(clock);
        var due = new DateTimeOffset(2026, 11, 1, 10, 0, 0, TimeSpan.Zero);

        Assert.False(deadline.IsLate(due));
        clock.Advance(TimeSpan.FromHours(2));
        Assert.True(deadline.IsLate(due));
    }
}

