public class FakeEmailSender : IEmailSender
{
    public List<(string To, string Subject)> Sent { get; } = [];
    public Task SendAsync(string to, string subject, string body)
    {
        Sent.Add((to, subject));
        return Task.CompletedTask;
    }
}

[Fact]
public async Task Deleting_a_course_deletes_its_enrollments()
{
    await using var db = await NewDatabaseAsync();
    db.Courses.Add(new Course { Id = 1, Title = "Math", Enrollments = [new() { StudentId = 1 }] });
    db.Students.Add(new Student { Id = 1, Name = "Sara", City = "Cairo", Year = 1 });
    await db.SaveChangesAsync();

    db.Courses.Remove(await db.Courses.SingleAsync());
    await db.SaveChangesAsync();

    Assert.Equal(0, await db.Enrollments.CountAsync());   // the cascade really happens in the database
}

public static async Task<CollegeContext> NewDatabaseAsync()
{
    var connection = new SqliteConnection("DataSource=:memory:");
    await connection.OpenAsync();   // the database lives as long as this connection

    var options = new DbContextOptionsBuilder<CollegeContext>()
        .UseSqlite(connection)
        .Options;

    var db = new CollegeContext(options);
    await db.Database.EnsureCreatedAsync();
    return db;
}

