import { TestBed } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { CourseApi } from './course-api';

describe('CourseApi', () => {
  it('loads the courses from /api/courses', () => {
    TestBed.configureTestingModule({ providers: [provideHttpClient(), provideHttpClientTesting()] });
    const api = TestBed.inject(CourseApi);
    const http = TestBed.inject(HttpTestingController);

    let titles: string[] = [];
    api.list().subscribe(list => (titles = list.map(c => c.title)));

    http.expectOne('/api/courses').flush([{ id: 1, title: 'Math', hours: 2 }]);
    expect(titles).toEqual(['Math']);
    http.verify();
  });
});

it('reports a 404 as "not found"', () => {
  TestBed.configureTestingModule({ providers: [provideHttpClient(), provideHttpClientTesting()] });
  const api = TestBed.inject(CourseApi);
  const http = TestBed.inject(HttpTestingController);

  let message = '';
  api.get(42).subscribe({ error: (err: Error) => (message = err.message) });

  http.expectOne('/api/courses/42').flush(null, { status: 404, statusText: 'Not Found' });
  expect(message).toBe('Course 42 was not found');
});

public interface ICourseRepository
{
    Task<Course?> FindAsync(int id);
    Task SaveAsync(Course course);
}

// A fake: works like the real thing, in memory
public class InMemoryCourseRepository : ICourseRepository
{
    private readonly Dictionary<int, Course> courses = [];
    public List<int> Saved { get; } = [];

    public Task<Course?> FindAsync(int id) => Task.FromResult(courses.GetValueOrDefault(id));
    public Task SaveAsync(Course course) { courses[course.Id] = course; Saved.Add(course.Id); return Task.CompletedTask; }
    public void Add(Course course) => courses[course.Id] = course;
}

[Fact]
public async Task Enrolling_sends_a_confirmation_email()
{
    var email = Substitute.For<IEmailSender>();
